/**
 * Refund pilot core — published-package imports only (CommonJS).
 * Used by refund-pilot-walkthrough.js
 */

const {
  honorEnforceDecision,
  honorObserveDecision,
  shouldDispatch,
} = require('@sector8/sdk');

const REFUND_FIXTURE = {
  environment: 'staging',
  tool_name: 'refund.create',
  currency: 'GBP',
  cap_amount: 100,
  under_cap_amount: 25,
  over_cap_amount: 250,
  expected_deny_reason: 'AMOUNT_LIMIT_EXCEEDED',
  agent_name: 'Refund Agent',
  caller_id: 'refund-pilot-walkthrough',
};

class FakeRefundDispatcher {
  constructor() {
    this.dispatches = [];
  }
  dispatch(record) {
    this.dispatches.push(record);
    return record;
  }
  get count() {
    return this.dispatches.length;
  }
  reset() {
    this.dispatches.length = 0;
  }
}

function refundEvaluateArguments(amount) {
  return {
    amount,
    currency: REFUND_FIXTURE.currency,
    order_id: 'ORD-PILOT-001',
    metadata: { agent_name: REFUND_FIXTURE.agent_name },
  };
}

function reportFromAttempt(mode, attempt, dispatched, extra = {}) {
  if (attempt.ok) {
    return {
      mode,
      decision: attempt.artifact.outcome,
      reason_code: attempt.artifact.reason_code,
      decision_trace_id: attempt.artifact.decision_trace_id,
      evidence_hash: attempt.artifact.evidence_hash,
      policy_version_id: attempt.artifact.policy_version_id,
      dispatched,
      ...extra,
    };
  }
  return {
    mode,
    decision: `FAIL:${attempt.kind}`,
    failure_kind: attempt.kind,
    dispatched,
    ...extra,
  };
}

function runEnforceOnce(attempt, dispatcher, record) {
  const before = dispatcher.count;
  honorEnforceDecision(attempt, () => dispatcher.dispatch(record));
  return reportFromAttempt('enforce', attempt, dispatcher.count - before);
}

function runObserveOnce(attempt, dispatcher, record) {
  const before = dispatcher.count;
  const { continued } = honorObserveDecision(attempt, () => {
    dispatcher.dispatch(record);
    return true;
  });
  return reportFromAttempt('observe', attempt, dispatcher.count - before, {
    continued,
  });
}

function assertEnforceEffects(attempt, dispatchedDelta) {
  if (shouldDispatch(attempt)) {
    if (dispatchedDelta !== 1) {
      throw new Error(`enforce ALLOW expected 1 dispatch, got ${dispatchedDelta}`);
    }
  } else if (dispatchedDelta !== 0) {
    throw new Error(`enforce non-ALLOW expected 0 dispatches, got ${dispatchedDelta}`);
  }
}

module.exports = {
  REFUND_FIXTURE,
  FakeRefundDispatcher,
  refundEvaluateArguments,
  runEnforceOnce,
  runObserveOnce,
  assertEnforceEffects,
};

