/**
 * Standalone refund pilot walkthrough — published @sector8/sdk only.
 *
 * Files needed in the same directory:
 *   refund-pilot-core.js
 *   refund-pilot-walkthrough.js  (this file)
 *
 *   npm install @sector8/sdk@1.0.4
 *   node refund-pilot-walkthrough.js --offline
 *   node refund-pilot-walkthrough.js          # live staging
 *
 * Env:
 *   SECTOR8_API_KEY, SECTOR8_CLIENT_ID
 *   SECTOR8_ENDPOINT or SECTOR8_BASE_URL = https://stgsdkapi.sector8.ai
 *   SECTOR8_UNSAFE_ENDPOINT=true
 */

const {
  Sector8Client,
  classifyEvaluateError,
  normalizeEvaluateResponse,
} = require('@sector8/sdk');

const {
  REFUND_FIXTURE,
  FakeRefundDispatcher,
  refundEvaluateArguments,
  runEnforceOnce,
  runObserveOnce,
  assertEnforceEffects,
} = require('./refund-pilot-core');

function resolveEndpointConfig() {
  const endpoint =
    process.env.SECTOR8_ENDPOINT ||
    process.env.SECTOR8_BASE_URL ||
    'https://sdkapi.sector8.ai';
  const unsafeEndpoint = ['1', 'true', 'yes'].includes(
    (process.env.SECTOR8_UNSAFE_ENDPOINT || '').toLowerCase(),
  );
  const isDefaultProd = /^https:\/\/sdkapi\.sector8\.ai\/?$/i.test(endpoint);
  if (!isDefaultProd && !unsafeEndpoint) {
    console.error(
      'Non-default endpoint requires SECTOR8_UNSAFE_ENDPOINT=true. ' +
        `Resolved endpoint: ${endpoint}`,
    );
    process.exit(2);
  }
  return { endpoint, unsafeEndpoint };
}

function artifactAttempt(outcome, reason_code) {
  return {
    ok: true,
    artifact: {
      decision: outcome,
      outcome,
      reason_code,
      decision_trace_id: `00000000-0000-4000-8000-${
        outcome === 'ALLOW' ? 'aaaaaaaaaaaa' : 'bbbbbbbbbbbb'
      }`,
      evidence_hash: `sim-hash-${outcome.toLowerCase()}`,
      policy_version_id: 'sim-policy',
      has_forensic_payload: outcome === 'DENY',
    },
  };
}

function printReport(label, report) {
  const note = report.simulated
    ? 'SIMULATED — these decision_trace_id values have no Decision Feed row; do not look them up.'
    : 'LIVE — compare decision_trace_id in Decision Feed (dashboard session, not the runtime key).';
  console.log(
    JSON.stringify(
      {
        label,
        ...report,
        fixture: {
          cap_amount: REFUND_FIXTURE.cap_amount,
          agent_name: REFUND_FIXTURE.agent_name,
          tool_name: REFUND_FIXTURE.tool_name,
        },
        note,
      },
      null,
      2,
    ),
  );
}

async function liveEvaluate(amount) {
  const { endpoint, unsafeEndpoint } = resolveEndpointConfig();
  const client = new Sector8Client({
    apiKey: process.env.SECTOR8_API_KEY,
    clientId: process.env.SECTOR8_CLIENT_ID,
    endpoint,
    unsafeEndpoint,
    enableAutoInstrumentation: false,
  });
  try {
    const raw = await client.evaluate({
      tool_name: REFUND_FIXTURE.tool_name,
      arguments: refundEvaluateArguments(amount),
      caller_id: REFUND_FIXTURE.caller_id,
      session_id: `refund-pilot-${Date.now()}`,
      role: 'developer',
    });
    return normalizeEvaluateResponse(raw);
  } catch (error) {
    return { ok: false, kind: classifyEvaluateError(error) };
  } finally {
    await client.close();
  }
}

async function main() {
  const offline = process.argv.includes('--offline');
  const dispatcher = new FakeRefundDispatcher();
  const record = {
    amount: REFUND_FIXTURE.under_cap_amount,
    currency: REFUND_FIXTURE.currency,
    order_id: 'ORD-PILOT-001',
  };

  console.log('=== Fixture contract ===');
  console.log(JSON.stringify(REFUND_FIXTURE, null, 2));

  const simulatedFailures = [
    {
      label: 'sim-deny',
      attempt: artifactAttempt('DENY', REFUND_FIXTURE.expected_deny_reason),
    },
    { label: 'sim-timeout', attempt: { ok: false, kind: 'timeout' } },
    { label: 'sim-auth', attempt: { ok: false, kind: 'auth_failure' } },
    { label: 'sim-malformed', attempt: { ok: false, kind: 'malformed' } },
    { label: 'sim-allow', attempt: artifactAttempt('ALLOW', 'ALLOW_PASS') },
  ];

  for (const { label, attempt } of simulatedFailures) {
    dispatcher.reset();
    const report = runEnforceOnce(attempt, dispatcher, record);
    report.simulated = true;
    assertEnforceEffects(attempt, report.dispatched);
    printReport(`enforce:${label}`, report);
  }

  for (const { label, attempt } of [
    {
      label: 'sim-deny',
      attempt: artifactAttempt('DENY', REFUND_FIXTURE.expected_deny_reason),
    },
    { label: 'sim-timeout', attempt: { ok: false, kind: 'timeout' } },
  ]) {
    dispatcher.reset();
    const report = runObserveOnce(attempt, dispatcher, record);
    report.simulated = true;
    if (report.dispatched !== 1 || !report.continued) {
      throw new Error(`observe ${label} expected continued + 1 fake dispatch`);
    }
    printReport(`observe:${label}`, report);
  }

  if (offline) {
    console.log('Offline proofs complete (--offline). Skipping live gate calls.');
    return 0;
  }

  if (!process.env.SECTOR8_API_KEY || !process.env.SECTOR8_CLIENT_ID) {
    console.error(
      'Live mode requires SECTOR8_API_KEY and SECTOR8_CLIENT_ID. Use --offline for simulated proofs.',
    );
    return 2;
  }

  // Live under-cap enforce
  {
    dispatcher.reset();
    const attempt = await liveEvaluate(REFUND_FIXTURE.under_cap_amount);
    const report = runEnforceOnce(attempt, dispatcher, {
      ...record,
      amount: REFUND_FIXTURE.under_cap_amount,
    });
    if (!attempt.ok) {
      console.error('MISMATCH: under-cap evaluate failed:', attempt);
      printReport('enforce:live-under-cap-MISMATCH', report);
      return 4;
    }
    if (attempt.artifact.outcome === 'DENY') {
      console.error(
        'MISMATCH: under-cap refund was DENY. Check fixture binding / agent / cap with Operator.',
      );
      printReport('enforce:live-under-cap-MISMATCH', report);
      return 4;
    }
    if (attempt.artifact.outcome !== 'ALLOW') {
      console.error('MISMATCH: under-cap expected ALLOW, got', attempt.artifact.outcome);
      printReport('enforce:live-under-cap-MISMATCH', report);
      return 4;
    }
    assertEnforceEffects(attempt, report.dispatched);
    printReport('enforce:live-under-cap', report);
  }

  // Live over-cap enforce
  {
    dispatcher.reset();
    const attempt = await liveEvaluate(REFUND_FIXTURE.over_cap_amount);
    const report = runEnforceOnce(attempt, dispatcher, {
      ...record,
      amount: REFUND_FIXTURE.over_cap_amount,
    });
    if (
      !attempt.ok ||
      attempt.artifact.outcome !== 'DENY' ||
      attempt.artifact.reason_code !== REFUND_FIXTURE.expected_deny_reason
    ) {
      console.error(
        `MISMATCH: over-cap expected DENY/${REFUND_FIXTURE.expected_deny_reason}.`,
        attempt,
      );
      printReport('enforce:live-over-cap-MISMATCH', report);
      return 4;
    }
    assertEnforceEffects(attempt, report.dispatched);
    printReport('enforce:live-over-cap', report);
  }

  // Live over-cap observe — must still be DENY, then continue
  {
    dispatcher.reset();
    const attempt = await liveEvaluate(REFUND_FIXTURE.over_cap_amount);
    if (
      !attempt.ok ||
      attempt.artifact.outcome !== 'DENY' ||
      attempt.artifact.reason_code !== REFUND_FIXTURE.expected_deny_reason
    ) {
      console.error(
        'MISMATCH: observe live over-cap expected DENY/' +
          REFUND_FIXTURE.expected_deny_reason,
        attempt,
      );
      return 4;
    }
    const report = runObserveOnce(attempt, dispatcher, {
      ...record,
      amount: REFUND_FIXTURE.over_cap_amount,
    });
    if (report.dispatched !== 1 || !report.continued) {
      throw new Error('live observe expected continued workflow + 1 fake dispatch');
    }
    printReport('observe:live-over-cap', report);
  }

  console.log(
    'Done. Copy LIVE decision_trace_id values into Decision Feed → Verify (dashboard login).',
  );
  return 0;
}

main()
  .then((code) => {
    process.exitCode = code || 0;
  })
  .catch((error) => {
    console.error(error);
    process.exitCode = 1;
  });
